        """Start a new time increment."""
        if assembly._nlgeom:
            if not (np.array_equal(assembly.sv["DispGradient"], 0)):
                # True when the problem have been updated once
                rot = SimRotation.from_matrix(assembly.sv["DR"].transpose(2, 0, 1))
